function own(re){var m=parts.filter(function(x){return re.test(x);});return m.length>0&&m.every(iU);}
if (ultParts.length) { text = ultParts.join(' ').toLowerCase(); }
var schools = [["Combat Technique","sword","blade","weapon","strik","attack","swing","fighting","combat","punch","fist","spear","axe","staff"],["Defense","defen","guard","parry","block","shield","brace"],["Tactics","tactic","strateg","formation","command","drill the squad","battlefield","positioning"],["Focus","focus","concentrat","meditat","channel","casting","breathing"],["Athletic Mobility","mobility","dodg","evasi","footwork","run","climb","vault","sprint","agility","acrobat","leap"],["Banter","banter","taunt","mock","jeer","insult","quip","heckl","trash talk","roast","comeback"]];
