}

ua_upgrade_caps.script:
var bR=new RegExp("\\b([Uu]pgrad|[Ii]mprov|[Ee]volv|[Rr]efin|[Pp]erfect|[Aa]dvanc)\\w* (?![Tt]o \\[)\\w"),cR=new RegExp("\\b(UPGRAD|IMPROV|EVOLV|REFIN|PERFECT|ADVANC)\\w* (?!TO \\[)\\w");function cO(x){return cR.test(x)&&!bR.test(x);}
var acts = check({type: 'action-text'});acts=(acts==null?[]:Array.isArray(acts)?acts:typeof acts==='object'?Object.keys(acts).map(function(k){return acts[k];}):[acts]).filter(function(x){return x!=null;}).map(String).filter(cO).map(function(x){return x.toLowerCase();});
if(acts.length){
var wd = "If this technique belongs to a power, magic or other system this world defines rather than to one of the six fighting disciplines, the rules of this world govern it and this beat does not apply. ";
var parts=(acts===null||acts===undefined)?[]:(Array.isArray(acts)?acts:(typeof acts==='object'?Object.keys(acts).map(function(k){return acts[k];}):[acts]));
parts=parts.filter(function(x){return x!=null;}).map(String).filter(function(x){return !cO(x);});var text=parts.join(' ').toLowerCase();
var schools = [["Combat Technique","sword","blade","weapon","strik","attack","swing","fighting","combat","punch","fist","spear","axe","staff"],["Defense","defen","guard","parry","block","shield","brace"],["Tactics","tactic","strateg","formation","command","drill the squad","battlefield","positioning"],["Focus","focus","concentrat","meditat","channel","casting","breathing"],["Athletic Mobility","mobility","dodg","evasi","footwork","run","climb","vault","sprint","agility","acrobat","leap"],["Banter","banter","taunt","mock","jeer","insult","quip","heckl","trash talk","roast","comeback"]];
var hit = null; var at = -1; for (var i = 0; i < schools.length; i++) { for (var k = 1; k < schools[i].length; k++) { var m = new RegExp('\\b' + schools[i][k]).exec(text); if (m && (at < 0 || m.index < at)) { hit = schools[i][0]; at = m.index; } } }
var tiers=[3,7,12,18,24];var cores=["Vanguard","Duelist","Reaver","Bulwark","Warden","Strategist","Channeler","Skirmisher","Provocateur","Marksman"];
function tierOf(n){var k=0;for(var q=0;q<tiers.length;q++){if(n>=tiers[q]){k=q+1;}}return k;}
function asMap(v){if(v!==null&&typeof v==='object'&&!Array.isArray(v)){return v;}var n=(typeof v==='number'||typeof v==='string')?Number(v):NaN;return isFinite(n)?{'the character':n}:{};}
var tr=check({type:'player-traits'});
function coreOf(who){var held=(tr&&typeof tr==='object'&&!Array.isArray(tr))?(tr[who]||[]):(Array.isArray(tr)?tr:[]);for(var c=0;c<cores.length;c++){if(held.indexOf(cores[c])>=0){return cores[c];}}return null;}
if (hit) { var raw=check({type:'skill-value',skill:hit});log('skill-value '+hit+' '+JSON.stringify(raw));var levels=asMap(raw);var lines=[];var any=false;
for(var who in levels){var n=Number(levels[who])||0;var tier=tierOf(n);var core=coreOf(who);if(tier>0){any=true;lines.push(who+': Tier '+tier+' ('+hit+' '+n+(core?', '+core+' core':'')+')');}else{lines.push(who+': no rung in '+hit+' yet ('+hit+' '+n+')');}}
  if (!any) { effects.push({type: 'story', instruction: wd + 'The player is trying to create a technique in ' + hit + ' but holds no rung there yet (below 3): the attempt is practice, not a technique. Show them reaching for it and falling short; the engine records no ability.'}); } else { effects.push({type: 'story', instruction: wd + 'The player is upgrading a technique of their own making to its next rank. Show the rank being earned: what the old form lacked and what the new one does. Do not narrate the rank into existence; the engine records it as a new ability that REPLACES the old one. It is bound to their unlocks: the rank takes the tier they now hold in the school of that technique and must sit above the rank it replaces, else this is refinement and nothing is recorded. If the engine records nothing this turn, the rank is still being earned: say so. Tiers by character: ' + lines.join('; ') + '.'}); } }
else { var lines=[];var per={};var anyAll=false;
for(var s=0;s<schools.length;s++){var sk=schools[s][0];var lv=asMap(check({type:'skill-value',skill:sk}));for(var who in lv){var n=Number(lv[who])||0;if(tierOf(n)>0){anyAll=true;}if(!per[who]){per[who]=[];}per[who].push(sk+' '+n+' (Tier '+tierOf(n)+')');}}
