}

ua_afflict_commit.script:
var T={"ledger":"ua_aff_ledger","effects":{"stunned":["Stunned","cc","loses its action this turn"],"knocked down":["Knocked Down","cc","spends its action getting up, and hits on it land one band better"],"rooted":["Rooted","cc","cannot move, close in or flee, but can still strike within reach"],"slowed":["Slowed","cc","acts last and cannot both move and attack"],"silenced":["Silenced","cc","cannot cast or use spoken powers"],"blinded":["Blinded","cc","its attacks land one band worse"],"taunted":["Taunted","cc","must target {by}"],"frightened":["Frightened","cc","will not approach what frightened it, and flees if cornered"],"bleeding":["Bleeding","dot","takes a {size} bleeding wound"],"poisoned":["Poisoned","dot","takes a {size} poison tick, and its attacks land one band worse"],"burning":["Burning","dot","takes a {size} burn, heavy for its size, until water, rolling or smothering puts it out"],"frostbitten":["Frostbitten","dot","takes a {size} frost tick and is Slowed: acts last and cannot both move and attack"],"corroded":["Corroded","dot","loses armor and guard, {size}, and Soaked makes it worse"],"withering":["Withering","dot","takes a {size} withering tick and cannot heal"],"shocked":["Shocked","dot","takes a {size} shock that jumps to one adjacent enemy, doubled if it is Soaked"]},"sizes":["light","serious","grievous"],"max_turns":3,"max_stacks":3,"max_targets":12,"head":"AFFLICTIONS, from the Ultimate Ability ledger. Apply every line this turn, exactly: ","ending":" Wearing off after this turn: ","tail":" Narrate each tick on its target; a Stunned or Knocked Down enemy takes no other action. These are already tracked: never write their tags again; tag only an affliction a move lands anew this turn. If the fiction ends one early, write [Cleared: Effect, Target]; if an afflicted enemy falls, [Defeated: Target]; when the fight ends, [Victory].","no_taunter":"whoever taunted it"};
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
var L=storage[T.ledger];
if(L===undefined||L===null){L={};}else if(!isObj(L)){log('ua_aff: ledger of type '+typeof L+' reset');L={};}
function key(n){var k=String(n).toLowerCase().replace(/\s+/g,' ').trim().replace(/[\s,.;:!-]+$/,'').replace(/^the /,'').replace(/(ves|fe)$/,'f');if(k.length>3&&/[^s]s$/.test(k)){k=k.slice(0,-1);}return k;}
function clean(n){return String(n).replace(/\s+/g,' ').trim().replace(/[\s,.;:!-]+$/,'').replace(/^the /i,'');}
function word(n){return String(n).toLowerCase().replace(/\s+/g,' ').trim();}
function total(e){var n=0;if(isObj(e)&&isObj(e.fx)){for(var f in e.fx){n+=Number(e.fx[f]&&e.fx[f].t)||0;}}return n;}
function size(){var n=0;for(var q in L){n++;}return n;}
var had=storage[T.ledger]!==undefined;
var raw=check({type:'story-text'});
var story=(raw===null||raw===undefined)?'':String(raw);
var PARSE=/^(.+?)[\s,]+(?:for\s+)?\(?\s*(\d+)\s*(?:turns?|rounds?)?(?:\s+left)?\s*\)?\s*(?:,\s*(?:taunted\s+)?(?:by\s+)?([^\d,\s][^,]*?))?\s*$/i;
var tags=[],b,br=/\[([^\[\]]{1,200})\]/g;
while((b=br.exec(story))!==null){tags.push(b[1]);}
var won=false;for(var v=0;v<tags.length;v++){if(/^\s*(victory|fight\s+over)\b/i.test(tags[v])){won=true;}}
if(won){L={};}
else{for(var i=0;i<tags.length;i++){
  var tag=tags[i],ci=tag.indexOf(':');if(ci<0){continue;}
  var head=word(tag.slice(0,ci)).replace(/\s*x\s*\d+$/,''),rest=tag.slice(ci+1).trim();
  if(head==='cleared'){
    var cc=rest.indexOf(','),ce=cc<0?null:T.effects[word(rest.slice(0,cc))],ck=cc<0?'':key(rest.slice(cc+1));
    if(ce&&isObj(L[ck])&&isObj(L[ck].fx)&&L[ck].fx[ce[0]]!==undefined){delete L[ck].fx[ce[0]];var left=false;for(var z in L[ck].fx){left=true;}if(!left){delete L[ck];}}
    else{log('ua_aff: ['+tag+'] matched nothing in the ledger (cleared)');}
    continue;
  }
  if(head==='defeated'){var dk=key(rest);if(L[dk]!==undefined){delete L[dk];}else{log('ua_aff: ['+tag+'] matched nothing in the ledger (defeated)');}continue;}
  var eff=T.effects[head],m=PARSE.exec(rest);
  if(!eff){if(m){log('ua_aff: unknown effect ['+tag+'] ignored');}continue;}
  if(!m){log('ua_aff: malformed tag ['+tag+'] ignored (want [Effect: Target turns])');continue;}
  var turns=Math.min(parseInt(m[2],10)||0,T.max_turns);
  if(turns<1){log('ua_aff: ['+tag+'] has no turns, ignored');continue;}
  var k=key(m[1]);if(!k){log('ua_aff: ['+tag+'] has no target, ignored');continue;}
  if(!isObj(L[k])||!isObj(L[k].fx)){
    if(!isObj(L[k])&&size()>=T.max_targets){var low=null;for(var q in L){if(low===null||total(L[q])<total(L[low])){low=q;}}log('ua_aff: ledger full, dropped '+low);delete L[low];}
    L[k]={name:clean(m[1]),fx:{}};
  }
  var old=isObj(L[k].fx[eff[0]])?L[k].fx[eff[0]]:null;
  var row={t:Math.max(turns,old?Math.min(Number(old.t)||0,T.max_turns):0),s:1};
  if(eff[1]==='dot'){row.s=Math.min((old?Number(old.s)||0:0)+1,T.max_stacks);}
  if(eff[0]==='Taunted'){row.by=m[3]?clean(m[3]):(old&&old.by?String(old.by):'');}
  L[k].fx[eff[0]]=row;
}}
if(had||size()>0){storage[T.ledger]=L;}

ua_afflict_tick.script:
var T={"ledger":"ua_aff_ledger","effects":{"stunned":["Stunned","cc","loses its action this turn"],"knocked down":["Knocked Down","cc","spends its action getting up, and hits on it land one band better"],"rooted":["Rooted","cc","cannot move, close in or flee, but can still strike within reach"],"slowed":["Slowed","cc","acts last and cannot both move and attack"],"silenced":["Silenced","cc","cannot cast or use spoken powers"],"blinded":["Blinded","cc","its attacks land one band worse"],"taunted":["Taunted","cc","must target {by}"],"frightened":["Frightened","cc","will not approach what frightened it, and flees if cornered"],"bleeding":["Bleeding","dot","takes a {size} bleeding wound"],"poisoned":["Poisoned","dot","takes a {size} poison tick, and its attacks land one band worse"],"burning":["Burning","dot","takes a {size} burn, heavy for its size, until water, rolling or smothering puts it out"],"frostbitten":["Frostbitten","dot","takes a {size} frost tick and is Slowed: acts last and cannot both move and attack"],"corroded":["Corroded","dot","loses armor and guard, {size}, and Soaked makes it worse"],"withering":["Withering","dot","takes a {size} withering tick and cannot heal"],"shocked":["Shocked","dot","takes a {size} shock that jumps to one adjacent enemy, doubled if it is Soaked"]},"sizes":["light","serious","grievous"],"max_turns":3,"max_stacks":3,"max_targets":12,"head":"AFFLICTIONS, from the Ultimate Ability ledger. Apply every line this turn, exactly: ","ending":" Wearing off after this turn: ","tail":" Narrate each tick on its target; a Stunned or Knocked Down enemy takes no other action. These are already tracked: never write their tags again; tag only an affliction a move lands anew this turn. If the fiction ends one early, write [Cleared: Effect, Target]; if an afflicted enemy falls, [Defeated: Target]; when the fight ends, [Victory].","no_taunter":"whoever taunted it"};
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
var L=storage[T.ledger];
if(L===undefined||L===null){L={};}else if(!isObj(L)){log('ua_aff: ledger of type '+typeof L+' reset');L={};}
var by={};for(var w in T.effects){by[T.effects[w][0]]=T.effects[w];}
var had=storage[T.ledger]!==undefined;var lines=[],ends=[];
for(var k in L){
  var e=L[k];if(!isObj(e)||!isObj(e.fx)){log('ua_aff: entry '+k+' dropped (bad shape)');delete L[k];continue;}
  var nm=String(e.name||k),parts=[];
  for(var f in e.fx){
    var ef=by[f],row=e.fx[f],t=isObj(row)?Math.floor(Number(row.t)):NaN;
    if(!ef||!(t>=1)){log('ua_aff: '+f+' on '+nm+' dropped');delete e.fx[f];continue;}
    t=Math.min(t,T.max_turns);
    var s=Math.min(Math.max(Math.floor(Number(row.s))||1,1),T.max_stacks);
    var line=ef[2].split('{size}').join(T.sizes[s-1]).split('{by}').join(row.by?String(row.by):T.no_taunter);
    parts.push(f+(ef[1]==='dot'&&s>1?' x'+s:'')+' ('+t+(t===1?' turn':' turns')+' left): '+line);
    if(t<=1){ends.push(f+' on '+nm);delete e.fx[f];}else{row.t=t-1;row.s=s;}
  }
  if(parts.length){lines.push(nm+': '+parts.join('; '));}
  var left=false;for(var z in e.fx){left=true;}if(!left){delete L[k];}
}
if(had||lines.length){storage[T.ledger]=L;}
if(lines.length){effects.push({type:'story',instruction:T.head+lines.join(' | ')+'.'+(ends.length?T.ending+ends.join(', ')+'.':'')+T.tail});}

art_commit.script:
var T = {"ladder":[{"word":"","gate":0,"mat":"common","dmg":1,"arm":30,"tool":1,"potency":"minor"},{"word":"Fine","gate":3,"mat":"refined","dmg":2,"arm":60,"tool":2,"potency":"moderate"},{"word":"Superior","gate":7,"mat":"rare","dmg":3,"arm":100,"tool":3,"potency":"strong"},{"word":"Masterwork","gate":12,"mat":"exotic","dmg":4,"arm":150,"tool":4,"potency":"potent"},{"word":"Legendary","gate":18,"mat":"legendary","dmg":6,"arm":220,"tool":5,"potency":"legendary"}],"xp":{"design":25,"craft":50,"upgrade":50},"next":{"design":"Craft it: Use Artisan: Craft to [{name}].","up":"Next for {name}: Use Artisan: Upgrade to [{name}] makes {to}; it needs {disc} {gate} and a {mat} material.","top":"{name} is Legendary, the top of the ladder."},"quest":"Artisan Ledger","objectives":["design","craft","superior","legendary"]};
function fill(t,o){return t.replace(/\{(\w+)\}/g,function(m,k){return Object.prototype.hasOwnProperty.call(o,k)?String(o[k]):m;});}
function full(b,q){return q?T.ladder[q].word+' '+b:b;}
function lc(s){return String(s).toLowerCase();}
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
function rowOf(v){var o=[0,0,0,0,0];if(v!==null&&typeof v==='object'){for(var i=0;i<5;i++){o[i]=Number(v[i])||0;}}else if(v!==undefined){log('art: a stock row of type '+typeof v+' read as empty');}return o;}
var raw=check({type:'story-text'});
var story=(raw===null||raw===undefined)?'':String(raw).toLowerCase();
var tick=Number(check({type:'game-tick'}));if(!isFinite(tick)){log('art: game-tick unreadable, using 0');tick=0;}
var P=Array.isArray(storage.art_pending)?storage.art_pending:[];
storage.art_pending=[];
var R=isObj(storage.art_recipes)?storage.art_recipes:{};
var S=isObj(storage.art_stock)?storage.art_stock:{};
var s0=isObj(storage.art_stats)?storage.art_stats:{},bq=Number(s0.best_q);
var st={designed:Number(s0.designed)||0,crafted:Number(s0.crafted)||0,upgraded:Number(s0.upgraded)||0,best_q:(s0.best_q===undefined||s0.best_q===null||!isFinite(bq))?-1:bq};
function findRecipe(n){for(var k in R){if(lc(k)===lc(n)){return k;}}return null;}
var xp=0,done=[],next=null,any=false,dropped=0;
for(var i=0;i<P.length;i++){
  var p=P[i];if(!p){continue;}
  if(p.tick!==tick&&p.tick!==tick-1){dropped++;continue;}
  var opts=(p.options||[]).slice().sort(function(a,b){return b.q-a.q;}),hit=null;
  for(var j=0;j<opts.length;j++){if(story.indexOf('['+String(opts[j].name).toLowerCase()+']')>=0){hit=opts[j];break;}}
  if(!hit){dropped++;continue;}
  if(p.op==='design'){
    if(findRecipe(p.base)){log('art: a second design of '+p.base+' this turn; the first stands');continue;}
    any=true;R[p.base]=p.recipe;st.designed++;xp+=T.xp.design;done.push('design');next=fill(T.next.design,{name:p.base});continue;
  }
  var key=findRecipe(p.base);
  if(!key){log('art: '+p.op+' of '+p.base+' has no recipe in the ledger; not recorded');continue;}
  var row=rowOf(S[key]);
  if(p.op==='upgrade'){if(row[p.from]<1){log('art: no '+full(key,p.from)+' left to upgrade; not recorded');continue;}row[p.from]--;st.upgraded++;xp+=T.xp.upgrade*hit.q;}
  else{st.crafted++;xp+=T.xp.craft;done.push('craft');}
  any=true;row[hit.q]++;S[key]=row;
  if(hit.q>st.best_q){st.best_q=hit.q;}
  var top=T.ladder.length-1;
  next=hit.q<top?fill(T.next.up,{name:full(key,hit.q),to:full(key,hit.q+1),disc:R[key].disc,gate:T.ladder[hit.q+1].gate,mat:T.ladder[hit.q+1].mat}):fill(T.next.top,{name:full(key,hit.q)});
}
if(dropped){log('art: '+dropped+' pending entries not recorded (no bracket echo this turn, or the tick moved more than one)');}
if(any){
  if(st.best_q>=2){done.push('superior');}
  if(st.best_q>=T.ladder.length-1){done.push('legendary');}
  storage.art_recipes=R;storage.art_stock=S;storage.art_stats=st;
  for(var k=0;k<T.objectives.length;k++){
    var ob=T.objectives[k],f='obj_'+T.quest+'_'+ob;
    if(done.indexOf(ob)<0||storage[f]===true){continue;}
    storage[f]=true;effects.push({type:'quest-objective-complete',questId:T.quest,objectiveId:ob});
  }
  if(xp>0){effects.push({type:'player-experience',operator:'add',value:xp});}
  if(next){effects.push({type:'quest-next-step-set',questId:T.quest,text:next,source:'narrative-event'});}
}

