function nameOf(r){if((r.match(/\[/g)||[]).length!==1||(r.match(/\]/g)||[]).length!==1){return null;}var m=/\[([^\[\]]*)\]/.exec(r);if(!m){return null;}var n=m[1].replace(/\s+/g,' ').trim();if(n.length<2||n.length>T.nameMax){return null;}return{name:n,after:r.slice(m.index+m[0].length)};}
function label(w){return T.label[w]||w;}
function rowOf(v){var o=[0,0,0,0,0];if(v!==null&&typeof v==='object'){for(var i=0;i<5;i++){o[i]=Number(v[i])||0;}}else if(v!==undefined){log('art: a stock row of type '+typeof v+' read as empty');}return o;}
var acts=check({type:'action-text'}),parts=[];
if(Array.isArray(acts)){for(var a0=0;a0<acts.length;a0++){if(acts[a0]!=null){parts.push({who:null,text:String(acts[a0])});}}}
else if(isObj(acts)){for(var k0 in acts){if(acts[k0]!=null){parts.push({who:k0,text:String(acts[k0])});}}}
else if(acts!=null){parts.push({who:null,text:String(acts)});}
var tick=Number(check({type:'game-tick'}));if(!isFinite(tick)){log('art: game-tick unreadable, using 0');tick=0;}
if(!isObj(storage.art_recipes)&&T.starters){if(storage.art_recipes!==undefined){log('art: art_recipes was not an object; reseeded with the starters');}storage.art_recipes=JSON.parse(JSON.stringify(T.starters));}
if(!isObj(storage.art_stock)){if(storage.art_stock!==undefined){log('art: art_stock was not an object; reset');}storage.art_stock={};}
var R=isObj(storage.art_recipes)?storage.art_recipes:{},S=storage.art_stock,P=[],WHO=null;
var OLD=(Array.isArray(storage.art_pending)?storage.art_pending:[]).filter(function(p){return p&&p.tick===tick;});
function findRecipe(n){for(var k in R){if(lc(k)===lc(n)){return k;}}return null;}
function asMap(v){if(isObj(v)){return v;}var n=(typeof v==='number'||typeof v==='string')?Number(v):NaN;return isFinite(n)?{'the character':n}:{};}
function best(d){var m=asMap(check({type:'skill-value',skill:d}));if(WHO!==null&&own(m,WHO)){return{lv:Number(m[WHO])||0,who:WHO+' has'};}var b=0;for(var k in m){var n=Number(m[k])||0;if(n>b){b=n;}}return{lv:b,who:"the party's best is"};}
function roll(){var v=check({type:'action-success-level'});var vs=(v===null||v===undefined)?[]:(isObj(v)?(WHO!==null&&own(v,WHO)?[v[WHO]]:Object.keys(v).map(function(k){return v[k];})):(Array.isArray(v)?v:[v]));var b=-1;for(var i=0;i<vs.length;i++){var x=T.order.indexOf(lc(vs[i]));if(x>b){b=x;}}return b;}
var place=lc([check({type:'party-location'}),check({type:'party-area'})].filter(function(x){return x!==null&&x!==undefined;}).join(' '));
function item(r,q){var L=T.ladder[q];var th=(!r.theme||r.theme==='plain')?'':', theme '+r.theme;if(r.kind==='weapon'){return 'Weapon, slot main-hand, damage +'+L.dmg+th;}if(r.kind==='armor'){return 'Armor, slot '+r.slot+', armor +'+L.arm+th;}if(r.kind==='tool'){return 'Tool, slot tool, '+r.disc+' +'+L.tool+th;}return 'Consumable, '+L.potency+' potency'+th;}
function stationLine(r,q){var s=wordIn(place,T.stations[r.disc])!==null?fill(T.beats.station_here,{station:label(r.station)}):fill(T.beats.station_check,{stations:T.stations[r.disc].map(label).join(' or ')});return q>=T.masterFrom?s+' '+T.beats.station_master:s;}
function used(key,q){return OLD.concat(P).filter(function(p){return p.op==='upgrade'&&p.base===key&&p.from===q;}).length;}
function held(key){var row=rowOf(S[key]),out=[];for(var q=0;q<T.words.length;q++){var n=row[q]-used(key,q);if(n>0){out.push(full(key,q)+' x'+n);}}return out.length?out.join(', '):'none of it';}
function act(nb){var sp=split(nb.name),key=findRecipe(sp.base);
if(!key){say(fill(T.beats.up_none,{name:nb.name,held:Object.keys(R).length?'no recipe by that name':'nothing yet, craft it first'}));return;}
var from=full(key,sp.q),top=T.words.length-1;
if(sp.q>=top){say(fill(T.beats.up_max,{name:from}));return;}
if(rowOf(S[key])[sp.q]-used(key,sp.q)<1){say(fill(T.beats.up_none,{name:from,held:held(key)}));return;}
var to=sp.q+1,L=T.ladder[to],rec=R[key],sk=best(rec.disc),lv=sk.lv;
if(lv<L.gate){say(fill(T.beats.up_skill,{name:from,to:full(key,to),disc:rec.disc,gate:L.gate,who:sk.who,lv:lv}));return;}
var r=roll();
var o={from:from,to:full(key,to),mat:L.mat,disc:rec.disc,lv:lv,station:stationLine(rec,to),item:item(rec,to),roll:r>=0?T.order[r]:''};
if(r>=0&&r<=1){say(fill(T.beats.up_lost,o));return;}
if(r===2){say(fill(T.beats.up_failed,o));return;}
P.push({op:'upgrade',tick:tick,base:key,from:sp.q,options:[{name:o.to,q:to}]});
say(fill(r<0?T.beats.up_roll:r===3?T.beats.up_mixed:r===T.order.length-1?T.beats.up_crit:T.beats.up_ok,o));}
var MARK=new RegExp(T.mark),seen=0;
for(var i=0;i<parts.length;i++){var m=MARK.exec(parts[i].text);if(!m){continue;}seen++;WHO=parts[i].who;var nb=nameOf(parts[i].text.slice(m.index+m[0].length));if(!nb){say(fill(T.beats.format,{op:T.op,example:T.example}));continue;}act(nb);}
if(!seen&&parts.length){log('art: the click condition fired but no actor text carries it: '+JSON.stringify(acts).slice(0,200));say(fill(T.beats.format,{op:T.op,example:T.example}));}
storage.art_pending=OLD.concat(P);

Power Control Training.script:
var t = Number(check({type: 'game-tick'})); if (!isFinite(t)) { t = 0; }
if (storage['pc_train'] !== undefined && t - storage['pc_train'] < 12) { effects.push({type: 'story', instruction: "The player completed another power-control exercise too soon after the last to rise again: narrate it as consolidation with no new level, and modest Power Strain for the effort."}); }
else { storage['pc_train'] = t; effects.push({type: 'player-skill', skill: 'Power Control', operator: 'add', value: 1, target: 'satisfyingPlayers'});
  effects.push({type: 'story', instruction: "The player completed a focused power-control exercise: Power Control rises one level (the engine awards it; never narrate a second). Show the one precision, efficiency or safe-output gain the exercise earned, and add modest Power Strain for the effort."}); }

Create or Test a Technique.script:
var lanes = ["Power Force", "Power Finesse", "Power Endurance", "Power Theory", "Power Control", "Power Presence"]; var per = {};
function asMap(v) { if (v !== null && typeof v === 'object' && !Array.isArray(v)) { return v; } var n = (typeof v === 'number' || typeof v === 'string') ? Number(v) : NaN; return isFinite(n) ? {'the character': n} : {}; }
for (var li = 0; li < lanes.length; li++) { var lv = asMap(check({type: 'skill-value', skill: lanes[li]})); for (var who in lv) { if (!per[who]) { per[who] = []; } per[who].push(lanes[li] + ' ' + (Number(lv[who]) || 0)); } }
var lines = []; for (var who2 in per) { lines.push(who2 + ': ' + per[who2].join(', ')); }
var strain = asMap(check({type: 'player-resource', resource: 'Power Strain'})); var sl = []; for (var who3 in strain) { sl.push(who3 + ' ' + (Number(strain[who3]) || 0)); }
effects.push({type: 'story', instruction: "The player is creating or testing a technique of their own. This turn is the TEST: resolve it as an ordinary action of their power with its normal Energy and Power Strain and an honest chance of failure; narrate what it did, what it cost and where it fell short. Record an ability only if the test succeeded and the function, limits and cost are now observable, and then exactly as Created Abilities says: the player's name for it, a description that is the whole mechanic with its band numbers (first test: Cantrip or Low-Level), and the tail [Lane: <power skill>]. If the engine records nothing this turn, the technique is still being worked out: say so, never that it is done. Power skills by character (the strongest is the natural lane): " + (lines.length ? lines.join('; ') : 'unknown') + '.' + " Power Strain by character: " + (sl.length ? sl.join(', ') : 'unknown') + '.'});

Team-Up Technique.script:
var lanes = ["Power Force", "Power Finesse", "Power Endurance", "Power Theory", "Power Control", "Power Presence"]; var per = {};
function asMap(v) { if (v !== null && typeof v === 'object' && !Array.isArray(v)) { return v; } var n = (typeof v === 'number' || typeof v === 'string') ? Number(v) : NaN; return isFinite(n) ? {'the character': n} : {}; }
for (var li = 0; li < lanes.length; li++) { var lv = asMap(check({type: 'skill-value', skill: lanes[li]})); for (var who in lv) { if (!per[who]) { per[who] = []; } per[who].push(lanes[li] + ' ' + (Number(lv[who]) || 0)); } }
var lines = []; for (var who2 in per) { lines.push(who2 + ': ' + per[who2].join(', ')); }
var strain = asMap(check({type: 'player-resource', resource: 'Power Strain'})); var sl = []; for (var who3 in strain) { sl.push(who3 + ' ' + (Number(strain[who3]) || 0)); }
effects.push({type: 'story', instruction: "Resolve this as a TEAM-UP: the declaring character's action and the named ally's are one combined technique this turn, each participant resolved from their own position, capability and willingness and paying their own Energy and Power Strain; if the ally is not present, able and willing, the combination breaks and the action resolves alone. A successful improvised team-up may stay a one-time tactic; record it only if the group chooses to keep it, as Improving and Team-Ups says. Power skills by character: " + (lines.length ? lines.join('; ') : 'unknown') + '.'});

hd_run.script:
var H={"Academy District Abandoned Training Facility":[1,20,"S"],"Central Tokyo Corporate Blacksite":[21,40,"S"],"Central Tokyo Underground Parasite Lab":[1,20,"S"],"Harborlight Beach: Breakwater Assault":[41,60,"E"],"Kurokawa Underground Den":[1,20,"S"],"Kurokawa Underworld Arms Exchange":[21,40,"S"],"Nightshade Exchange: Tidewater Escrow Vault":[41,60,"E"],"Oblivion's Crucible: The Last Descent":[81,100,"E"],"Obsidian Crown: Quiet Ward Annex":[41,60,"E"],"Odaiba Shoreline: Glass Reef Assault":[41,60,"E"],"Old Tokyo Cursed Shrine Archive":[1,20,"S"],"Old Tokyo: Buried Shrine Blitz":[41,60,"E"],"Reclamation Bunker 9: Coldline Archive":[61,80,"E"],"Saltmarsh Tower: Regent's Citadel":[61,80,"E"],"Shinjuku Curse-Infested Entertainment District":[21,40,"S"],"Sunken Pumpworks: Vermine Warren":[21,40,"S"],"The Black Rail: Null-Line Terminus":[61,80,"E"],"Tokyo Bay Flooded Transit Hub":[21,40,"S"],"Tokyo Docks Smuggler Hideout":[1,20,"S"],"Tokyo Skyteeth: Ascension Raid":[61,80,"E"]},M=[["Blackout","the power is out: darkness, flashlights, sound and smell matter; stealth is stronger and so are ambushes."],["Reinforced","the defenders expected trouble: one extra enemy per fight and a reinforcement wave before the boss."],["Bounty Target","a wanted lieutenant is inside; the boss carries a bounty and rolls a second loot roll when it falls."],["Alarm Clock","an alarm is already counting down: dawdling brings lockdown, reinforcements or a burning objective."],["Volatile Ground","the structure or the air is unstable: hazards are more frequent and powers can set them off."],["Skeleton Crew","few defenders, each tougher and smarter than usual; fights are short and dangerous."],["Rival Crew","another crew is raiding the same place: race them, bargain with them, or fight them for the loot."],["Lucky Haul","a fresh shipment just arrived: loot rolls lean better this run."]],LEN={"Q":"Quick run: one compact area. Entry, one fight or hazard, the miniboss as the finale, extraction. One loot roll; half Delver Points.","S":"Standard run: the five areas in order (entry, encounters and hazards, objective and optional loot, recovery and miniboss, boss and extraction), no filler between them. Miniboss and boss each roll loot.","E":"Extended raid: the five areas each played as two or three beats (8 to 15 sections), with a mid-run checkpoint objective. Miniboss and boss roll loot, plus a raid cache roll at extraction; Delver Points x1.5."},RESET=40;
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
function txt(v){if(v===null||v===undefined){return '';}if(Array.isArray(v)){return v.join(' ');}if(isObj(v)){var o=[];for(var k in v){o.push(String(v[k]));}return o.join(' ');}return String(v);}
function hash(s){var h=0;for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))%9973;}return h;}
var loc=check({type:'party-location'});
var tick=Number(check({type:'game-tick'}));if(!isFinite(tick)){log('hd: game-tick unreadable, using the last good one');tick=Number(storage.hd_tick)||0;}else{storage.hd_tick=tick;}
var R=isObj(storage.hd_runs)?storage.hd_runs:{};
var act=txt(check({type:'action-text'}));
var want=/quick (run|clear)|speed ?run/i.test(act)?'Q':/full run|standard run/i.test(act)?'S':/extended|raid run|long run/i.test(act)?'E':null;
var inside=loc!==null&&loc!==undefined&&Object.prototype.hasOwnProperty.call(H,loc);
var cur=isObj(storage.hd_cur)?storage.hd_cur:null;
if(cur&&cur.loc!==loc&&isObj(R[cur.loc])){
 if(R[cur.loc].state==='active'){R[cur.loc].state='idle';effects.push({type:'story',instruction:'The run at '+cur.loc+' lapsed: the party left without clearing it, so it pays no completion rewards; the next visit starts a fresh run.'});}
 storage.hd_cur=null;cur=null;
}
if(!inside&&want){storage.hd_req={len:want,tick:tick};}
if(inside){
var h=H[loc];
var r=isObj(R[loc])?R[loc]:{run:0,clears:0,pity:0,state:'idle',boss:false,seen:-99};
if(r.state==='cleared'&&tick-r.at<RESET){
 if(tick-r.seen>=10){r.seen=tick;effects.push({type:'story',instruction:'HIDEOUT RECOVERING: '+loc+' was cleared '+(tick-r.at)+' turns ago. Its rooms are quiet, a few stragglers at most, no boss and no completion loot; a fresh run opens in about '+(RESET-(tick-r.at))+' turns.'});}
}else if(r.state!=='active'){
 var req=isObj(storage.hd_req)&&tick-Number(storage.hd_req.tick)<=10?storage.hd_req.len:null;storage.hd_req=null;
 var len=want||req||h[2];
 r.run+=1;r.state='active';r.mb=false;r.bd=false;r.len=len;
 r.mod=M[(tick+r.run*3+hash(loc))%M.length][0];
 var md=M[(tick+r.run*3+hash(loc))%M.length][1];
 var lv=check({type:'player-level'}),low=null;
 if(isObj(lv)){for(var n in lv){var x=Number(lv[n]);if(isFinite(x)&&(low===null||x<low)){low=x;}}}else if(isFinite(Number(lv))){low=Number(lv);}
 var warn=(low!==null&&low<h[0])?' DANGER: the party\'s lowest level is '+low+', under this place\'s band; show the warning signs before the first unavoidable fight and never weaken the content.':'';
 var boss=r.boss?' Its named boss fell on an earlier run: the successor its notes describe holds the boss area.':' Its named miniboss and boss (in its location notes) wait in their areas.';
 effects.push({type:'story',instruction:'HIDEOUT RUN '+r.run+' - '+loc+' (levels '+h[0]+'-'+h[1]+'). '+LEN[len]+' Modifier: '+r.mod+': '+md+boss+warn});
 if(!storage.hd_ledger_open){storage.hd_ledger_open=true;effects.push({type:'quest-init',operator:'set',value:'Hideout Ledger'});effects.push({type:'quest-accept',operator:'set',value:'Hideout Ledger'});}
}
R[loc]=r;storage.hd_cur={loc:loc,seen:tick};
}
storage.hd_runs=R;

hd_ledger.script:
var H={"Academy District Abandoned Training Facility":[1,20,"S"],"Central Tokyo Corporate Blacksite":[21,40,"S"],"Central Tokyo Underground Parasite Lab":[1,20,"S"],"Harborlight Beach: Breakwater Assault":[41,60,"E"],"Kurokawa Underground Den":[1,20,"S"],"Kurokawa Underworld Arms Exchange":[21,40,"S"],"Nightshade Exchange: Tidewater Escrow Vault":[41,60,"E"],"Oblivion's Crucible: The Last Descent":[81,100,"E"],"Obsidian Crown: Quiet Ward Annex":[41,60,"E"],"Odaiba Shoreline: Glass Reef Assault":[41,60,"E"],"Old Tokyo Cursed Shrine Archive":[1,20,"S"],"Old Tokyo: Buried Shrine Blitz":[41,60,"E"],"Reclamation Bunker 9: Coldline Archive":[61,80,"E"],"Saltmarsh Tower: Regent's Citadel":[61,80,"E"],"Shinjuku Curse-Infested Entertainment District":[21,40,"S"],"Sunken Pumpworks: Vermine Warren":[21,40,"S"],"The Black Rail: Null-Line Terminus":[61,80,"E"],"Tokyo Bay Flooded Transit Hub":[21,40,"S"],"Tokyo Docks Smuggler Hideout":[1,20,"S"],"Tokyo Skyteeth: Ascension Raid":[61,80,"E"]},P=[10, 20, 35, 50, 75],RESET=40;
var NAMES=['Common','Uncommon','Rare','Epic','Legendary'];
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
var story=String(check({type:'story-text'})||'');
var R=isObj(storage.hd_runs)?storage.hd_runs:{};
// the run's own hideout (the party may already have walked out on the turn it extracts or abandons)
var loc=isObj(storage.hd_cur)?storage.hd_cur.loc:check({type:'party-location'});
if(loc===null||loc===undefined||!Object.prototype.hasOwnProperty.call(H,loc)){log('hd: tag outside a hideout ignored');}
else if(!isObj(R[loc])||R[loc].state!=='active'){log('hd: tag with no active run at '+loc+' ignored');}
else{
var h=H[loc],r=R[loc],b=Math.min(5,Math.max(1,Math.floor((h[0]-1)/20)+1));
var tick=Number(check({type:'game-tick'}));if(!isFinite(tick)){tick=Number(storage.hd_tick)||0;}
var out=[];
function roll(src){
 var w=[50,28,15,5.5,1.5];
 var s=Math.min((r.pity||0)*4,40)+(src==='boss'?10:0)+(h[0]>=61?5:0)+(r.mod==='Lucky Haul'?10:0);
 s=Math.min(s,w[0]);w[0]-=s;w[2]+=s*0.6;w[3]+=s*0.3;w[4]+=s*0.1;
 var x=Math.random()*100,i=0,acc=w[0];while(x>=acc&&i<4){i+=1;acc+=w[i];}
 if(src==='boss'&&!r.clears&&i<1){i=1;}
 r.pity=i>=2?0:(r.pity||0)+1;
 return 'LOOT ROLL ('+src+', '+loc+'): '+NAMES[i]+'. Reveal one concrete '+NAMES[i]+' item the '+src+' carried or guarded, fitting the place.';
}
if(/\[Miniboss Down\]/.test(story)&&!r.mb){r.mb=true;out.push(roll('miniboss'));}
if(/\[Boss Down\]/.test(story)&&!r.bd){r.bd=true;r.boss=true;out.push(roll('boss'));if(r.mod==='Bounty Target'){out.push(roll('bounty'));}}
if(/\[Hideout Cleared\]/.test(story)){
 if(r.len==='E'){out.push(roll('raid cache'));}
 var pts=Math.round(P[b-1]*(r.len==='Q'?0.5:r.len==='E'?1.5:1));
 r.state='cleared';r.at=tick;r.seen=tick;r.clears=(r.clears||0)+1;
 effects.push({type:'player-resource',resource:'Delver Points',operator:'add',value:pts,target:'allPlayers'});
 out.push('HIDEOUT CLEARED: '+loc+', clear '+r.clears+' (+'+pts+' Delver Points). It recovers for about '+RESET+' turns before a fresh run.');
 var F=isObj(storage.hd_flags)?storage.hd_flags:{};
 var obs=[['first_clear',true],['band2',b===2],['raid',b>=3],['crucible',loc==='Oblivion\'s Crucible: The Last Descent']];
 for(var j=0;j<obs.length;j++){if(obs[j][1]&&!F[obs[j][0]]){F[obs[j][0]]=true;effects.push({type:'quest-objective-complete',questId:'Hideout Ledger',objectiveId:obs[j][0]});}}
 storage.hd_flags=F;
}else if(/\[Run Abandoned\]/.test(story)){r.state='idle';out.push('RUN ABANDONED at '+loc+': no completion rewards; the next visit starts a fresh run.');}
if(out.length){effects.push({type:'story',instruction:out.join(' ')});}
R[loc]=r;storage.hd_runs=R;
}

Post-Combat Recovery.script:
var t=Number(check({type:'game-tick'}));if(!isFinite(t)){log('pcr: game-tick unreadable, using the last good one');t=Number(storage.pcr_tick)||0;}else{storage.pcr_tick=t;}
var last=Number(storage.pcr_last);
if(isFinite(last)&&t-last<8){log('pcr: paid '+(t-last)+' turns ago, no second payout');}else{storage.pcr_last=t;effects.push({type:'player-resource',resource:'health',operator:'add',value:15,target:'allPlayers'});effects.push({type:'story',instruction:'POST-COMBAT RECOVERY: the fight is over. Recover a modest portion of lost health after combat ends when stable and no longer immediately endangered. The engine has added 15 health to every player; narrate that breath and add nothing more. Limits: Do not restore full health automatically. Serious injuries, critical conditions, coma, and explicit injury states remain until appropriate treatment, time, rest, or abilities address them. Stabilization: If a character is near death, unconscious, critically injured, or medically unstable, stabilize them before ordinary recovery.'});}

bp_engine.script:
var T={"reg":"bp_registry","state":"bp_state","frame":"BOSS PHASES: {name} breaks into phase {phase} of {bars}. Open this beat with the line [Phase {phase}/{bars}] on its own. {beat} {name} is not dead and not dying: the health is full again, a fresh bar, and the fight goes on.","generic":{"2":["The foe throws off the restraint it fought with until now: a new form, a new weapon or a new tactic, shown in one clear image."],"3":["The foe stops holding back: a new form, a new weapon or a new tactic, shown in one clear image.","The foe's last reserve breaks open: the most dangerous thing it can do, shown plainly, and it fights as if nothing after this matters."]},"cap":10,"last":"BOSS PHASES LAST STAND: {name} is struck down before its final phase. In its death throes it unleashes that last form in one desperate final strike: {beat} Then it falls for good; it does not rise again.","floor":70,"floorMax":90,"perPlayer":7};
function isObj(v){return v!==null&&typeof v==='object'&&!Array.isArray(v);}
function own(o,k){return Object.prototype.hasOwnProperty.call(o,k);}
function fill(t,o){return t.replace(/\{(\w+)\}/g,function(m,k){return own(o,k)?String(o[k]):m;});}
var REG=isObj(storage[T.reg])?storage[T.reg]:{};
if(!isObj(storage[T.state])){storage[T.state]={};}
var S=storage[T.state];
var tick=Number(check({type:'game-tick'}));
var pl=check({type:'player-level'}),np=isObj(pl)?Math.max(1,Object.keys(pl).length):1;
var keys=Object.keys(REG).sort(),deferred=[];
for(var i=0;i<keys.length;i++){
  var k=keys[i],r=isObj(REG[k])?REG[k]:{};
  var bars=Number(r.bars);
  if(bars!==2&&bars!==3){log('bp: '+k+' has bars '+JSON.stringify(r.bars)+'; only 2 or 3 are phased');continue;}
  var fl=(r.floor===undefined)?T.floor:Number(r.floor);if(!(fl>=0)){fl=T.floor;}if(fl>T.floorMax){fl=T.floorMax;}
  var s=isObj(S[k])?S[k]:null;
  if(check({type:'npc-in-scene',npc:k})!==true&&!(s&&isFinite(tick)&&tick-Number(s.seen)<=1)){continue;}
  var h=check({type:'npc-health',npc:k}),p=check({type:'npc-health-percent',npc:k});
  if(h===undefined&&p===undefined){continue;}
  if(typeof h!=='number'||typeof p!=='number'||!isFinite(h)||!isFinite(p)){log('bp: '+k+' health unreadable: '+JSON.stringify([h===undefined?null:h,p===undefined?null:p]));continue;}
  if(check({type:'npc-in-party',npc:k})===true){if(s){s.seen=tick;}continue;}
  if(s&&isFinite(tick)&&isFinite(Number(s.seen))&&tick-Number(s.seen)>1&&s.max>0){
    delete s.pend;delete s.retry;
    if(h<=0){log('bp: '+k+' back at 0 after time away; left to the engine');s.phase=bars;}
    else if(h>=s.max&&s.phase!==1){log('bp: '+k+' fresh fight after time away: bar 1 (was '+s.phase+')');s.phase=1;}
  }
  if(!s){
    if(!(p>0)){log('bp: '+k+' first seen at 0 health; not phased this turn');continue;}
    var mx=Number(r.max);if(!(mx>0)){mx=Math.round(h*100/p);}
    s={phase:1,max:mx};S[k]=s;
  }
  if(isFinite(tick)){s.seen=tick;}
  var prevP=Number(s.lastP);
  if(s.lastP!==undefined&&isFinite(Number(s.lastP))&&p<Number(s.lastP)){var d=Number(s.lastP)-p;if(!(Number(s.maxHit)>=d)){s.maxHit=d;}}
  s.lastP=p;
  var line=Math.max(fl,Math.min(T.floorMax,fl+(np-1)*T.perPlayer),Math.min(T.floorMax,Math.ceil(1.5*(Number(s.maxHit)||0))));
  if(s.phase<bars&&h<=0){
    if(effects.length+1>T.cap){deferred.push(k);continue;}
    var lb=Array.isArray(r.breaks)?r.breaks[bars-2]:undefined;
    effects.push({type:'story',instruction:fill(T.last,{name:k,beat:(typeof lb==='string'&&lb.trim())?lb.trim():T.generic[String(bars)][bars-2]})});
    log('bp: '+k+' struck to 0 in bar '+s.phase+' of '+bars+': last stand, left to the engine');delete s.pend;delete s.retry;s.phase=bars;continue;
  }
  var beats=Array.isArray(r.breaks)?r.breaks:[];
  function beat(ph){var b=beats[ph-2];return fill(T.frame,{name:k,phase:ph,bars:bars,beat:(typeof b==='string'&&b.trim())?b.trim():T.generic[String(bars)][ph-2]});}
  if(s.pend!==undefined){
    if(p>line){delete s.pend;delete s.retry;}
    else if(!s.retry){
      if(effects.length+2>T.cap){deferred.push(k);continue;}
      log('bp: '+k+' still at 0 the turn after its phase '+s.phase+' break; refill set again, phase held');
      effects.push({type:'npc-health',npc:k,operator:'add',value:s.pend});effects.push({type:'story',instruction:beat(s.phase)});
      s.retry=true;continue;
    }
    else{log('bp: '+k+' refill did not land twice; left to the engine');delete s.pend;delete s.retry;s.phase=bars;continue;}
  }
  if(s.phase>=bars||p>line){continue;}
  if(effects.length+2>T.cap){deferred.push(k);continue;}
  effects.push({type:'npc-health',npc:k,operator:'add',value:s.max});
  effects.push({type:'story',instruction:beat(s.phase+1)});
  s.phase++;s.pend=s.max;s.lastP=100;delete s.retry;
}
if(deferred.length){log('bp: effect cap reached; breaks deferred to next turn: '+deferred.join(', '));}
